			const sessionItem: IChatSessionItem = {
				id: session.id,
				name: session.name,
				lastMessage: session.lastMessage
			};
			this.sessions.push(sessionItem);
			this._onDidChangeChatSessionItems.fire(this.sessions);
		});
	}

	private registerResponseListener(): void {
		this.chatService.onDidReceiveChatResponse(response => {
			const session = this.sessions.find(s => s.id === response.sessionId);
